using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "BehenianHowlAction", menuName = "Data/Battle/Battle Actions/Sothis/BehenianHowl Action")]
public class BehenianHowlAction : GainSandsOfTimeBasedAction
{
	[Header("Soul Heat")]
	[SerializeField]
	protected SoulHeat soulHeat;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return GetSandsOfTimeAmount(actionValue) > 0;
	}

	public override int GetSandsOfTimeAmount(int amount = 0)
	{
		return soulHeat.SoulHeatCounter * amount;
	}
}
